function retrieveCityListValue(n){const i=n.params.data,t=i.id,r=$("#representation-list").select2("data"),u=r[0].id||0;loadCompanyByCityId(t);loadRepresentation(u,t)}function retrieveCompanyListValue(n){const t=n.params.data,i=t.id,r=$("#cities-province--list").select2("data"),u=r[0].id||0;loadRepresentation(i,u)}function loadCompanyByCityId(n){let t="/Company/CityCompanies";n!==0&&(t+="?cityId="+n);$("#company-list").load(t,function(){createSelect2Dropdown("#representation-list","لطفا مرکز را انتخاب کنید");$("#representation-list").on("select2:select",retrieveCompanyListValue)})}function loadCitiesByCompanyId(){$("#cities-province").load("/Company/GetAllCities",function(){createSelect2Dropdown("#cities-province--list","لطفا شهر را انتخاب کنید");$("#cities-province--list").on("select2:select",retrieveCityListValue)})}function loadRepresentation(n,t){Number(t)===0&&(t=null);Number(n)===0&&(n=null);const i=`
        <div class="w-100 d-flex justify-content-center">
            <div class="d-flex flex-column align-items-center gap-4">
                <span class="spinner-border text-dark" role="status" aria-hidden="true"></span>
                <span class="sr-only text-dark">درحال دریافت اطلاعات، لطفا منتظر بمانید...</span>
            </div>
        </div>
    `;document.getElementById("representationTableContainer").innerHTML=i;$.ajax({type:"Post",url:"/Representation/GetRepresentationsByCityAndCompanyId?cityId="+t+"&companyId="+n,contentType:"application/json; charset=utf-8",dataType:"json",success:function(n){var i,r,t;for($("#representationTableContainer").html(""),i="<tbody>",r="<thead class='bg-primary text-white'><tr id='a' style='background-color:#028BFF' ><th class='thColumns' style='text-align: center;'>نام نمایندگی<\/th><th class='' style='text-align: center;'>شهر<\/th><th class='desktop' style='text-align: center;'>تلفن<\/th><th class='desktop' style='text-align: center;'>آدرس<\/th><\/thead>",t=0;t<n.length;t++)i=i+"<tr><td style='text-align: center;'><span id='lblTitle'>"+n[t].title+"<\/span><\/td><td style='text-align: center;'><span id='lblCityTitle'>"+n[t].cityTitle+"<\/span><\/td><td style='text-align: center;'><span id='lblTelephone'>"+n[t].telephone+"<\/span><\/td><td style='text-align: center;'><span id='lblFullAddress'>"+n[t].fullAddress+"<\/span><\/td><\/tr>";$("#representationTableContainer").append("<div id='ooo' style='width: 100%;float: right;margin-right:1px;'><table id='representationRes' class='table table-bordered pt-3 table-hover dt-responsive' cellspacing='0' width='99.8%'>"+r+i+"<\/tbody><\/table><\/div>");$("#representationRes").DataTable({responsive:!0,language:{decimal:"",emptyTable:"داده ای مطابق با عبارت جستجو شده یافت نشد",info:"نمایش _START_ تا _END_ از _TOTAL_ کل ورودی ها",infoEmpty:"نمایش 0 تا 0 از 0 کل رکورد",infoFiltered:"(فیلتر شده از _MAX_ تعداد رکورد)",infoPostFix:"",thousands:",",lengthMenu:"نمایش _MENU_ تا از کل ورودی ها",loadingRecords:"بارگزاری...",processing:"",search:"جستجو: ",zeroRecords:"داده ای مطابق با عبارت جستجو شده یافت نشد",paginate:{first:"اول",last:"آخر",next:"بعدی",previous:"قبلی"},zeroRecords:"داده ای مطابق با عبارت جستجو شده یافت نشد",infoFiltered:"(فیلتر شده از _MAX_ تعداد رکورد)"}})}})}loadCitiesByCompanyId();loadCompanyByCityId(0);loadRepresentation(0,0);